            "outcome_key": "outcome_01",
            "outcome_rank": 1,
            "outcome_name": "Incident any age-related macular degeneration",
            "study_design_type": "non_randomized_intervention_study",
            "study_design_subtype": "retrospective_cohort",
            "recommended_rob_tool_id": "robins_i",
            "recommended_rob_tool_name": "ROBINS-I for non-randomized studies of interventions",
            "recommended_assessment_level": "specific_result",
