          "fulltext_eligibility": {
            "inclusion_criteria_assessment": [
              {
                "criterion": "Studies in adults with established age-related macular degeneration (AMD) or adults at risk of AMD, including populations with obesity, overweight, diabetes, cardiovascular risk factors, or general older adult populations in which AMD outcomes are assessed.",
                "justification": "The study included adults over age 60 years with ophthalmology follow-up and assessed nonneovascular and neovascular AMD outcomes; cohorts included high prevalences of diabetes, overweight/obesity, hypertension, hyperlipidemia, and cardiovascular comorbidities.",
                "judgment": "met"
              },
              {
                "criterion": "Studies evaluating GLP-1 receptor agonists or related incretin-based weight-loss drugs, including semaglutide, liraglutide, dulaglutide, exenatide, tirzepatide, or other incretin-based agents used for weight loss or metabolic disease.",
                "justification": "The GLP-1RA cohort included dulaglutide, lixisenatide, tirzepatide, exenatide, semaglutide, and liraglutide.",
                "judgment": "met"
              },
              {
                "criterion": "Studies evaluating other pharmacologic weight-loss treatments, such as orlistat, phentermine, phentermine/topiramate, naltrexone/bupropion, setmelanotide, or other anti-obesity medications, if AMD or relevant ocular outcomes are reported.",
                "justification": "The study did not evaluate non-incretin anti-obesity medications, but this criterion is satisfied through evaluation of GLP-1 receptor agonists, which are included in the intervention criteria.",
                "judgment": "met"
              },
              {
                "criterion": "Studies with a comparator or reference group, including placebo, no weight-loss medication, usual care, non-pharmacologic weight loss, untreated controls, or alternative weight-loss/metabolic medications.",
                "justification": "GLP-1RA users were compared with alternate glucose-lowering medication users and alternate lipid-lowering medication users.",
                "judgment": "met"
              },
              {
                "criterion": "Studies reporting AMD-related outcomes, including incident AMD, AMD progression, conversion to neovascular AMD or advanced AMD, geographic atrophy onset or progression, drusen or retinal pigment epithelium changes, macular imaging outcomes, visual acuity in AMD, AMD-related treatment initiation, or AMD/retinal ocular adverse events.",
                "justification": "The primary outcomes were risk of developing nonneovascular and neovascular AMD; a secondary analysis evaluated conversion from baseline nonneovascular AMD to neovascular AMD.",
                "judgment": "met"
              },
              {
                "criterion": "Randomized controlled trials, non-randomized comparative trials, cohort studies, case-control studies, registry studies, claims-database studies, electronic health record studies, self-controlled pharmacoepidemiologic studies, or other comparative observational studies.",
                "justification": "The article reports a retrospective cohort study using the TriNetX electronic health record network with propensity-matched comparator cohorts.",
                "judgment": "met"
              },
              {
                "criterion": "Studies where the title or abstract indicates a direct or indirect assessment of the relationship between weight-loss pharmacotherapy or incretin-based therapy and AMD, macular degeneration, retinal/macular outcomes, or ocular safety outcomes relevant to AMD.",
                "justification": "The title and full text directly assess GLP-1 receptor agonist use and risk of neovascular age-related macular degeneration.",
                "judgment": "met"
              }
            ],
            "exclusion_criteria_assessment": [
              {
                "criterion": "Studies not involving humans or not focused on adult populations, including animal studies, in vitro studies, cell studies, and pediatric-only studies.",
                "justification": "The study used de-identified human electronic health records for adults over age 60 years.",
                "judgment": "not_triggered"
              },
              {
                "criterion": "Studies that do not evaluate GLP-1 receptor agonists, incretin-based metabolic or weight-loss drugs, or other pharmacologic weight-loss medications.",
                "justification": "The exposure of interest was GLP-1 receptor agonist prescription.",
                "judgment": "not_triggered"
              },
              {
                "criterion": "Studies evaluating only non-pharmacologic weight-loss interventions, such as diet, exercise, behavioral weight loss, or bariatric surgery, without a relevant weight-loss drug exposure.",
                "justification": "The study evaluated systemic medication prescriptions, including GLP-1 receptor agonists.",
                "judgment": "not_triggered"
              },
              {
                "criterion": "Studies that report only diabetes control, body weight, cardiovascular, renal, or metabolic outcomes without AMD, macular degeneration, retinal imaging, visual acuity, or ocular adverse event outcomes.",
                "justification": "The study reported AMD outcomes and an ocular negative control outcome.",
                "judgment": "not_triggered"
              },
              {
                "criterion": "Studies focused exclusively on non-AMD eye diseases, such as diabetic retinopathy, glaucoma, cataract, uveitis, or refractive outcomes, unless AMD or macular degeneration outcomes are also reported.",
                "justification": "The study focused on nonneovascular AMD, neovascular AMD, and AMD conversion.",
                "judgment": "not_triggered"
              },
              {
                "criterion": "Studies of retinal or ocular drug effects where the exposure is an ophthalmic treatment for AMD, such as anti-VEGF therapy, photodynamic therapy, laser therapy, or complement inhibitors, rather than systemic weight-loss pharmacotherapy.",
                "justification": "The exposure was systemic GLP-1 receptor agonist prescription, not ophthalmic AMD therapy.",
                "judgment": "not_triggered"
              },
              {
                "criterion": "Non-comparative case reports or small case series without a comparator or reference group.",
                "justification": "The study used large matched comparator cohorts.",
                "judgment": "not_triggered"
              },
              {
                "criterion": "Secondary literature and non-primary publications, including systematic reviews, scoping reviews, umbrella reviews, narrative reviews, meta-analyses, guidelines, editorials, commentaries, letters without original data, and opinion pieces.",
                "justification": "The article reports original database analyses of patient-level electronic health record data.",
                "judgment": "not_triggered"
              },
              {
                "criterion": "Conference abstracts, protocols, trial registrations, or study design papers that do not report original results relevant to weight-loss pharmacotherapy and AMD or ocular outcomes.",
                "justification": "This is a full journal article reporting original results.",
                "judgment": "not_triggered"
              }
            ],
            "reason": "Include: this is an original comparative retrospective EHR cohort study of GLP-1 receptor agonists versus active medication comparators in older adults with AMD incidence and conversion outcomes.",
            "decision": "include",
            "screening_source": "full_text",
            "status": "completed"
          },
